contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // amount is the Ether the external caller may send to this test contract before invoking the suicide call
    function run(uint256 amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        // ensure the caller actually funded this test contract with the declared amount
        require(address(this).balance >= amount);

        // observe balances before the call
        uint256 beforeC = address(c).balance;
        uint256 beforeThis = address(this).balance;

        // perform the state-changing call at top-level and record whether it reverted
        bool reverted;
        c.sudicideAnyone(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        // If call succeeded then C's balance must be zero and this contract's balance must be >= prior balance (it may receive funds).
        // Otherwise (reverted) no further requirement.
        assert(reverted || (address(c).balance == 0 && address(this).balance >= beforeThis));
    }

    receive() external payable {}
}

